/** A level reading for one audio channel, in dBFS. */
export interface ChannelLevel {
  /** Sample peak in dBFS. `-Infinity` is digital silence. */
  peakDb: number;
  /** RMS level in dBFS, when the source measures it. */
  rmsDb?: number;
}

/** One metering update: one entry per channel (1 = mono, 2 = stereo). */
export interface MeterFrame {
  channels: ChannelLevel[];
}

/** One visualisation update from an analyser. */
export interface VisualFrame {
  /** Frequency bands, 0..1 each, low to high. */
  bands: Float32Array;
  /** Ring buffer of recent broadband levels, 0..1 each. */
  history: Float32Array;
  /** Index of the oldest entry in `history`. */
  historyStart: number;
  /** Number of valid entries in `history`. */
  historyLength: number;
  /** Time of the newest history entry, in the requestAnimationFrame clock. */
  historyUpdatedAt?: number;
  /** Minimum time between entries, used for playback delay. 0 disables smoothing. */
  historyIntervalMs?: number;
  /** Last entry removed from a full history ring, for its scrolling edge. */
  historyPreviousLevel?: number;
  /** Raw time-domain samples, −1..1, for line and scope drawing. */
  timeDomain?: Float32Array;
  /** Sample peak of this frame in dBFS. */
  peakDb: number;
}

/** Anything that can push frames to subscribers. */
export interface FrameSource<T> {
  subscribe: (listener: (frame: T) => void) => () => void;
}

export type MeterZoneName = "ok" | "warn" | "clip";

/** A colour zone of a meter, starting at `fromDb` and running to the next zone. */
export interface MeterZone {
  fromDb: number;
  zone: MeterZoneName;
}

/** Maps a value (usually dB) to a 0..1 position on a control, and back. */
export interface Taper {
  toPosition: (value: number) => number;
  toValue: (position: number) => number;
}

export type Orientation = "horizontal" | "vertical";

/** Default bottom of a meter's range, in dBFS. */
export const DEFAULT_MIN_DB = -60;
/** Default top of a meter's range, in dBFS. */
export const DEFAULT_MAX_DB = 0;
/** Digital silence. */
export const SILENCE_DB = Number.NEGATIVE_INFINITY;

const AMPLITUDE_DB_FACTOR = 20;
const MINUS_SIGN = "−";
const INFINITY_SIGN = "∞";

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

/** Decibels to linear gain. `-Infinity` gives 0. */
export const dbToGain = (db: number): number => {
  if (db === SILENCE_DB) {
    return 0;
  }
  return 10 ** (db / AMPLITUDE_DB_FACTOR);
};

/** Linear gain to decibels. 0 (or less) gives `-Infinity`. */
export const gainToDb = (gain: number): number => {
  if (gain <= 0) {
    return SILENCE_DB;
  }
  return AMPLITUDE_DB_FACTOR * Math.log10(gain);
};

/** dBFS to a 0..1 level, linear in dB over `minDb..maxDb`, clamped. */
export const dbToLevel = (
  db: number,
  minDb: number = DEFAULT_MIN_DB,
  maxDb: number = DEFAULT_MAX_DB
): number => {
  if (!(db > minDb)) {
    return 0;
  }
  return clamp((db - minDb) / (maxDb - minDb), 0, 1);
};

/** A 0..1 level back to dBFS over `minDb..maxDb`. The inverse of `dbToLevel`. */
export const levelToDb = (
  level: number,
  minDb: number = DEFAULT_MIN_DB,
  maxDb: number = DEFAULT_MAX_DB
): number => minDb + clamp(level, 0, 1) * (maxDb - minDb);

/**
 * Clamps a dB value to a range. With `allowSilence`, `-Infinity` passes
 * through instead of becoming `minDb`.
 */
export const clampDb = (
  db: number,
  minDb: number,
  maxDb: number,
  options: { allowSilence?: boolean } = {}
): number => {
  if (db === SILENCE_DB && options.allowSilence) {
    return SILENCE_DB;
  }
  if (Number.isNaN(db)) {
    return minDb;
  }
  return clamp(db, minDb, maxDb);
};

export interface FormatDbOptions {
  /** Digits after the decimal point. Default 1. */
  decimals?: number;
  /** Append " dB". Default true. */
  unit?: boolean;
  /**
   * `auto` shows "+" for positive values and "−" for negative ones,
   * `negative` only shows "−", `never` shows no sign. Default `auto`.
   */
  sign?: "auto" | "negative" | "never";
  /** At or below this value, show "−∞". Default `-Infinity`. */
  floorDb?: number;
}

/** Formats decibels for display: "−12.3 dB", "+3.0 dB", "−∞ dB". */
export const formatDb = (db: number, options: FormatDbOptions = {}): string => {
  const {
    decimals = 1,
    unit = true,
    sign = "auto",
    floorDb = SILENCE_DB,
  } = options;
  const suffix = unit ? " dB" : "";

  // No reading yet. Two hyphens rather than a dash: hosts such as Videorc ban
  // the em dash from user-facing copy.
  if (Number.isNaN(db)) {
    return `--${suffix}`;
  }
  if (db === SILENCE_DB || db <= floorDb) {
    const prefix = sign === "never" ? "" : MINUS_SIGN;
    return `${prefix}${INFINITY_SIGN}${suffix}`;
  }

  const rounded = Number(db.toFixed(decimals));
  const magnitude = Math.abs(rounded).toFixed(decimals);

  if (rounded === 0 || sign === "never") {
    return `${magnitude}${suffix}`;
  }
  if (rounded < 0) {
    return `${MINUS_SIGN}${magnitude}${suffix}`;
  }
  const plus = sign === "auto" ? "+" : "";
  return `${plus}${magnitude}${suffix}`;
};

/** Sample peak of a block of samples, in dBFS. */
export const peakDb = (samples: Iterable<number>): number => {
  let peak = 0;
  for (const sample of samples) {
    const magnitude = Math.abs(sample);
    if (magnitude > peak) {
      peak = magnitude;
    }
  }
  return gainToDb(peak);
};

/** RMS level of a block of samples, in dBFS. */
export const rmsDb = (samples: Iterable<number>): number => {
  let sumOfSquares = 0;
  let count = 0;
  for (const sample of samples) {
    sumOfSquares += sample * sample;
    count += 1;
  }
  if (count === 0) {
    return SILENCE_DB;
  }
  return gainToDb(Math.sqrt(sumOfSquares / count));
};

import { dbToGain, gainToDb } from "$LIB$/audio/decibels.js";

/** How a meter moves between readings. All times are in milliseconds. */
export interface BallisticsOptions {
  /** Time constant for rising levels. 0 jumps instantly. */
  attackMs: number;
  /** Time constant for falling levels. 0 drops instantly. */
  releaseMs: number;
  /** How long the peak-hold marker stays before it starts to fall. 0 disables it. */
  peakHoldMs: number;
  /** Time constant for the peak-hold marker's fall. */
  peakReleaseMs: number;
}

export const BALLISTICS = {
  instant: { attackMs: 0, peakHoldMs: 0, peakReleaseMs: 0, releaseMs: 0 },
  peak: { attackMs: 15, peakHoldMs: 1200, peakReleaseMs: 600, releaseMs: 350 },
  vu: { attackMs: 300, peakHoldMs: 0, peakReleaseMs: 300, releaseMs: 300 },
} as const satisfies Record<string, BallisticsOptions>;

export type BallisticsPreset = keyof typeof BALLISTICS;

export type BallisticsInput = BallisticsPreset | Partial<BallisticsOptions>;

export const resolveBallistics = (
  input: BallisticsInput = "peak"
): BallisticsOptions => {
  if (typeof input === "string") {
    return BALLISTICS[input];
  }
  return { ...BALLISTICS.peak, ...input };
};

export interface BallisticsState {
  /** The smoothed level in dBFS. */
  db: number;
  /** The peak-hold level in dBFS. */
  holdDb: number;
}

export interface Ballistics {
  step: (inputDb: number, nowMs: number) => BallisticsState;
  reset: () => void;
}

const smoothingFactor = (elapsedMs: number, timeConstantMs: number): number => {
  if (timeConstantMs <= 0) {
    return 1;
  }
  return 1 - Math.exp(-elapsedMs / timeConstantMs);
};

/**
 * Creates a meter ballistics integrator. Smoothing runs on linear amplitude,
 * so a falling level drops at a steady rate in dB, like a hardware meter.
 */
export const createBallistics = (input?: BallisticsInput): Ballistics => {
  const options = resolveBallistics(input);
  let amplitude = 0;
  let holdAmplitude = 0;
  let holdUntilMs = 0;
  let lastMs: number | null = null;

  const reset = () => {
    amplitude = 0;
    holdAmplitude = 0;
    holdUntilMs = 0;
    lastMs = null;
  };

  const step = (inputDb: number, nowMs: number): BallisticsState => {
    const target = dbToGain(inputDb);

    if (lastMs === null) {
      amplitude = target;
    } else {
      const elapsedMs = Math.max(0, nowMs - lastMs);
      const timeConstant =
        target > amplitude ? options.attackMs : options.releaseMs;
      amplitude +=
        (target - amplitude) * smoothingFactor(elapsedMs, timeConstant);
    }

    if (options.peakHoldMs <= 0) {
      holdAmplitude = amplitude;
    } else if (amplitude >= holdAmplitude) {
      holdAmplitude = amplitude;
      holdUntilMs = nowMs + options.peakHoldMs;
    } else if (nowMs > holdUntilMs && lastMs !== null) {
      const elapsedMs = Math.max(0, nowMs - Math.max(lastMs, holdUntilMs));
      holdAmplitude -=
        (holdAmplitude - amplitude) *
        smoothingFactor(elapsedMs, options.peakReleaseMs);
    }

    lastMs = nowMs;
    return { db: gainToDb(amplitude), holdDb: gainToDb(holdAmplitude) };
  };

  return { reset, step };
};

import type { MeterZone, MeterZoneName } from "$LIB$/audio/types.js";

/** Green below −20 dBFS, amber from −20, red from −9: the thresholds streamers know. */
export const DEFAULT_ZONES: MeterZone[] = [
  { fromDb: Number.NEGATIVE_INFINITY, zone: "ok" },
  { fromDb: -20, zone: "warn" },
  { fromDb: -9, zone: "clip" },
];

/** A level at or above this counts as clipping for a clip light. */
export const CLIP_THRESHOLD_DB = -1;
/** How long a clip light stays on after the last clip. */
export const CLIP_HOLD_MS = 1500;

/** The zone a level falls in. */
export const zoneForDb = (
  db: number,
  zones: MeterZone[] = DEFAULT_ZONES
): MeterZoneName => {
  let current: MeterZoneName = "ok";
  for (const zone of zones) {
    if (db >= zone.fromDb) {
      current = zone.zone;
    }
  }
  return current;
};

import { clamp, DEFAULT_MIN_DB } from "$LIB$/audio/decibels.js";
import type { Taper } from "$LIB$/audio/types.js";

const DEFAULT_FADER_MAX_DB = 6;
const DEFAULT_UNITY_POSITION = 0.75;
const AUDIO_CURVE_EXPONENT = 2;

/** Equal distance per unit across the range. */
export const linearTaper = (min: number, max: number): Taper => ({
  toPosition: (value) => {
    if (!(value > min)) {
      return 0;
    }
    return clamp((value - min) / (max - min), 0, 1);
  },
  toValue: (position) => min + clamp(position, 0, 1) * (max - min),
});

export interface AudioTaperOptions {
  minDb?: number;
  maxDb?: number;
  /** Where 0 dB sits on the travel, 0..1. Default 0.75. */
  unityPosition?: number;
}

/**
 * A console-style fader law: more travel around 0 dB, a fast fall to the
 * bottom of the range, and linear headroom above 0 dB.
 */
export const audioTaper = ({
  minDb = DEFAULT_MIN_DB,
  maxDb = DEFAULT_FADER_MAX_DB,
  unityPosition = DEFAULT_UNITY_POSITION,
}: AudioTaperOptions = {}): Taper => {
  const anchorDb = Math.min(0, maxDb);
  const unity = maxDb > 0 ? clamp(unityPosition, 0, 1) : 1;

  const toPosition = (db: number): number => {
    if (!(db > minDb)) {
      return 0;
    }
    if (db >= maxDb) {
      return 1;
    }
    if (db >= anchorDb) {
      return unity + ((db - anchorDb) / (maxDb - anchorDb)) * (1 - unity);
    }
    const ratio = (db - anchorDb) / (minDb - anchorDb);
    const travel = 1 - ratio ** (1 / AUDIO_CURVE_EXPONENT);
    return travel * unity;
  };

  const toValue = (position: number): number => {
    const clamped = clamp(position, 0, 1);
    if (clamped >= unity) {
      if (unity >= 1) {
        return anchorDb;
      }
      return anchorDb + ((clamped - unity) / (1 - unity)) * (maxDb - anchorDb);
    }
    const travel = unity > 0 ? clamped / unity : 0;
    return anchorDb + (minDb - anchorDb) * (1 - travel) ** AUDIO_CURVE_EXPONENT;
  };

  return { toPosition, toValue };
};

/** Logarithmic law for frequency and time parameters. `min` must be above 0. */
export const logTaper = (min: number, max: number): Taper => {
  const span = Math.log(max / min);
  return {
    toPosition: (value) => {
      if (!(value > min)) {
        return 0;
      }
      return clamp(Math.log(value / min) / span, 0, 1);
    },
    toValue: (position) => min * Math.exp(clamp(position, 0, 1) * span),
  };
};

export type TaperInput = "linear" | "audio" | "log" | Taper;

/** Resolves a taper name or object for a range. */
export const resolveTaper = (
  taper: TaperInput,
  min: number,
  max: number
): Taper => {
  if (typeof taper !== "string") {
    return taper;
  }
  if (taper === "audio") {
    return audioTaper({ maxDb: max, minDb: min });
  }
  if (taper === "log") {
    return logTaper(min, max);
  }
  return linearTaper(min, max);
};

import { clamp } from "$LIB$/audio/decibels.js";

/** `AnalyserNode.minDecibels` default. */
export const SPECTRUM_MIN_DB = -100;
/** `AnalyserNode.maxDecibels` default. */
export const SPECTRUM_MAX_DB = -30;

const POWER_DB_FACTOR = 10;

/** `count + 1` band edges in Hz, spaced evenly on a log scale. */
export const logBandEdges = (
  count: number,
  minHz: number,
  maxHz: number
): Float32Array => {
  const edges = new Float32Array(count + 1);
  const ratio = maxHz / minHz;
  for (let index = 0; index <= count; index += 1) {
    edges[index] = minHz * ratio ** (index / count);
  }
  return edges;
};

export interface BandsFromSpectrumOptions {
  minDb?: number;
  maxDb?: number;
}

/**
 * Reduces analyser frequency data (dB per bin) to 0..1 bands between the given
 * edges. Writes into `out` and returns it.
 */
export const bandsFromSpectrum = (
  spectrumDb: Float32Array,
  sampleRate: number,
  edges: Float32Array,
  out: Float32Array,
  {
    minDb = SPECTRUM_MIN_DB,
    maxDb = SPECTRUM_MAX_DB,
  }: BandsFromSpectrumOptions = {}
): Float32Array => {
  const binCount = spectrumDb.length;
  const hzPerBin = sampleRate / 2 / binCount;
  const bandCount = Math.min(out.length, edges.length - 1);

  for (let band = 0; band < bandCount; band += 1) {
    const low = Math.floor((edges[band] ?? 0) / hzPerBin);
    const high = Math.max(
      low + 1,
      Math.ceil((edges[band + 1] ?? 0) / hzPerBin)
    );
    const first = clamp(low, 0, binCount - 1);
    const last = clamp(high, first + 1, binCount);
    let power = 0;
    for (let bin = first; bin < last; bin += 1) {
      power += 10 ** ((spectrumDb[bin] ?? minDb) / POWER_DB_FACTOR);
    }
    const meanDb = POWER_DB_FACTOR * Math.log10(power / (last - first));
    out[band] = clamp((meanDb - minDb) / (maxDb - minDb), 0, 1);
  }
  return out;
};

/**
 * Fits `length` values from a ring buffer, starting at `start`, into
 * `out.length` values. Each output takes the loudest value in its span.
 */
export const resampleLevels = (
  source: ArrayLike<number>,
  start: number,
  length: number,
  out: Float32Array
): Float32Array => {
  const size = source.length;
  const count = out.length;

  if (size === 0 || length <= 0 || count === 0) {
    out.fill(0);
    return out;
  }

  for (let index = 0; index < count; index += 1) {
    const from = Math.floor((index * length) / count);
    const to = Math.max(from + 1, Math.floor(((index + 1) * length) / count));
    let loudest = 0;
    for (let offset = from; offset < to; offset += 1) {
      const value = source[(start + offset) % size] ?? 0;
      if (value > loudest) {
        loudest = value;
      }
    }
    out[index] = loudest;
  }
  return out;
};

import { resampleLevels } from "$LIB$/audio/bands.js";
import { clamp } from "$LIB$/audio/decibels.js";

const RELEASE_PER_FRAME = 0.86;
const FRAME_MS = 16.67;
const SIGNAL_THRESHOLD = 0.02;
const MS_PER_SECOND = 1000;
/** Bars this close to their target have nothing left to animate. */
const SETTLE_EPSILON = 0.002;

/** What bars do with no signal. */
export type BarIdle = "static" | "pulse" | "wave";

export interface BarLevelsOptions {
  barCount: number;
  idle: BarIdle;
  /** Runs a sweep, for connecting or thinking states. */
  loading: boolean;
  /** Resting bar size, 0..1. */
  minLevel: number;
  /** Symmetric around the middle bar, lows in the centre. */
  mirrored: boolean;
  /** No release smoothing, idle animation or sweep. */
  reducedMotion: boolean;
}

export interface BarLevels {
  /** The level each bar shows, 0..1, never below `minLevel`. */
  levels: Float32Array;
  /**
   * Advances to `nowMs` with the latest input levels (resampled to the bar
   * count). Returns true when the input is above the signal floor.
   */
  step: (nowMs: number, input: ArrayLike<number> | null) => boolean;
  /**
   * True after a step that left nothing to animate: every bar is at its
   * target, and no idle animation or loading sweep is running.
   */
  readonly settled: boolean;
}

const idleLevel = (idle: BarIdle, index: number, seconds: number) => {
  if (idle === "pulse") {
    return 0.1 * (0.5 + 0.5 * Math.sin(seconds * Math.PI * 1.6));
  }
  if (idle === "wave") {
    return 0.16 * (0.5 + 0.5 * Math.sin(seconds * 4 - index * 0.55));
  }
  return 0;
};

const sweepLevel = (index: number, count: number, seconds: number) => {
  const span = count + 6;
  const position = ((seconds * count * 0.9) % span) - 3;
  return 0.55 * Math.exp(-((index - position) ** 2) / 3);
};

const targetIndexFor = (
  index: number,
  count: number,
  half: number,
  mirrored: boolean
) => {
  if (!mirrored) {
    return index;
  }
  return Math.min(half - 1, Math.floor(Math.abs(index - (count - 1) / 2)));
};

const loudestOf = (values: Float32Array) => {
  let loudest = 0;
  for (const value of values) {
    loudest = Math.max(loudest, value);
  }
  return loudest;
};

/**
 * Bar levels shared by the bar visualizers: input resampled to the bar count,
 * instant attack with a smooth release, mirroring, idle animations and the
 * loading sweep.
 */
export const createBarLevels = ({
  barCount,
  idle,
  loading,
  minLevel,
  mirrored,
  reducedMotion,
}: BarLevelsOptions): BarLevels => {
  const half = mirrored ? Math.ceil(barCount / 2) : barCount;
  const targets = new Float32Array(half);
  const current = new Float32Array(barCount);
  const levels = new Float32Array(barCount).fill(minLevel);
  let lastMs = 0;
  let settled = false;

  const extraLevel = (index: number, seconds: number, quiet: boolean) => {
    if (loading && !reducedMotion) {
      return sweepLevel(index, barCount, seconds);
    }
    return quiet ? idleLevel(idle, index, seconds) : 0;
  };

  const readInput = (input: ArrayLike<number> | null) => {
    if (input && input.length > 0) {
      resampleLevels(input, 0, input.length, targets);
    } else {
      targets.fill(0);
    }
  };

  const step = (nowMs: number, input: ArrayLike<number> | null) => {
    const elapsed = lastMs === 0 ? FRAME_MS : nowMs - lastMs;
    lastMs = nowMs;
    const release = reducedMotion
      ? 0
      : RELEASE_PER_FRAME ** (elapsed / FRAME_MS);
    const seconds = nowMs / MS_PER_SECOND;
    readInput(input);
    const active = loudestOf(targets) >= SIGNAL_THRESHOLD;
    const quiet = !(reducedMotion || active);
    const animating =
      (loading && !reducedMotion) || (quiet && idle !== "static");
    let converged = true;

    for (let index = 0; index < barCount; index += 1) {
      const target = Math.max(
        targets[targetIndexFor(index, barCount, half, mirrored)] ?? 0,
        extraLevel(index, seconds, quiet)
      );
      const previous = current[index] ?? 0;
      const next =
        target >= previous
          ? target
          : previous * release + target * (1 - release);
      current[index] = next;
      levels[index] = clamp(Math.max(minLevel, next), 0, 1);
      if (Math.abs(next - target) > SETTLE_EPSILON) {
        converged = false;
      }
    }
    settled = converged && !animating;
    return active;
  };

  return {
    levels,
    get settled() {
      return settled;
    },
    step,
  };
};

import { createBarLevels } from "$LIB$/audio/bar-levels.js";
import { clamp } from "$LIB$/audio/decibels.js";
import type { VisualFrame } from "$LIB$/audio/types.js";

const MS_PER_SECOND = 1000;
const FRAME_MS = 16.67;
const MAX_STEP_SECONDS = 0.05;
const TWO_PI = Math.PI * 2;
/** Below this the line counts as silent. */
const SIGNAL_THRESHOLD = 0.02;
/** Share of the distance to the new shape still left after one frame. */
const EASE_PER_FRAME = 0.45;
/** Loudness left after one frame of silence. */
const LOUDNESS_RELEASE = 0.92;

/** Cycles across the width, drift in radians per second and weight of each band group, lows first. */
const WAVE_PARTIALS = [
  { cycles: 1.5, drift: 0.8, weight: 0.6 },
  { cycles: 2.5, drift: -1.3, weight: 0.4 },
  { cycles: 4, drift: 2.1, weight: 0.25 },
  { cycles: 6.5, drift: -3.2, weight: 0.16 },
] as const;

/** Scope mode lifts quiet signals by at most this much. */
const SCOPE_MAX_GAIN = 4;
/** Scope mode scales its running peak to this height. */
const SCOPE_TARGET = 0.9;
/** Share of the scope's running peak left after one frame. */
const SCOPE_PEAK_RELEASE = 0.985;

/** Widths per second the loading pulse travels. */
const LOADING_SPEED = 0.55;
/** Where the loading pulse rests with reduced motion: the middle. */
const LOADING_REST_SECONDS = 0.7 / LOADING_SPEED;

/** Most points a line can have. */
export const WAVE_LINE_MAX_POINTS = 513;

/**
 * `wave` is a smooth wave shaped by the frequency bands. `scope` is the
 * signal itself, like an oscilloscope.
 */
export type WaveLineMode = "wave" | "scope";

export interface WaveLineOptions {
  mode: WaveLineMode;
  /** Runs a pulse along the line instead of following the signal. */
  loading: boolean;
  /** Visual gain. */
  sensitivity: number;
  /** No drift or easing: the line jumps to each new shape. */
  reducedMotion: boolean;
}

export interface WaveLine {
  /** Points in use, left to right. */
  count: number;
  /** Height at each point, −1..1, up positive, eased toward the latest shape. */
  heights: Float32Array;
  /** Highest point of the latest shape before easing, 0..1. It jumps on sudden rises. */
  peak: number;
  /** How loud the line is, 0..1: its highest point, released slowly. */
  loudness: number;
  /**
   * Advances to `nowMs` with the latest frame, over `count` points. Returns
   * true when there is a signal.
   */
  step: (nowMs: number, frame: VisualFrame | null, count: number) => boolean;
}

/**
 * Where the signal first rises through zero in its first quarter, between
 * samples, so a steady tone stands still. 0 when it never does.
 */
export const triggerIndex = (samples: ArrayLike<number>): number => {
  const limit = Math.floor(samples.length / 4);
  for (let index = 1; index <= limit; index += 1) {
    const before = samples[index - 1] ?? 0;
    const after = samples[index] ?? 0;
    if (before < 0 && after >= 0) {
      return index - 1 + -before / (after - before);
    }
  }
  return 0;
};

const peakOf = (values: ArrayLike<number>, count: number) => {
  let peak = 0;
  for (let index = 0; index < count; index += 1) {
    peak = Math.max(peak, Math.abs(values[index] ?? 0));
  }
  return peak;
};

/** Fits three quarters of the samples, from the trigger, into `count` heights. */
const fillScope = (
  samples: ArrayLike<number>,
  out: Float32Array,
  count: number,
  gain: number
) => {
  const start = triggerIndex(samples);
  const span = Math.floor(samples.length * 0.75) - 1;
  for (let point = 0; point < count; point += 1) {
    const position = start + (span * point) / (count - 1);
    const index = Math.floor(position);
    const before = samples[index] ?? 0;
    const after = samples[Math.min(samples.length - 1, index + 1)] ?? before;
    const value = before + (after - before) * (position - index);
    out[point] = clamp(value * gain, -1, 1);
  }
};

/** A short wave packet that travels left to right. */
const loadingPulse = (position: number, seconds: number) => {
  const center = ((seconds * LOADING_SPEED) % 1.4) - 0.2;
  const envelope = Math.exp(-((position - center) ** 2) / 0.012);
  return 0.6 * envelope * Math.sin(TWO_PI * (position * 7 - seconds * 2.5));
};

/**
 * The shape of a single line across the width, shared by the line
 * visualizers: a drifting wave shaped by the frequency bands, a triggered
 * oscilloscope trace, or a loading pulse, eased from frame to frame.
 */
export const createWaveLine = ({
  loading,
  mode,
  reducedMotion,
  sensitivity,
}: WaveLineOptions): WaveLine => {
  const targets = new Float32Array(WAVE_LINE_MAX_POINTS);
  const bands = createBarLevels({
    barCount: WAVE_PARTIALS.length,
    idle: "static",
    loading: false,
    minLevel: 0,
    mirrored: false,
    reducedMotion,
  });
  const phases = new Float32Array(WAVE_PARTIALS.length);
  const state = {
    count: 2,
    heights: new Float32Array(WAVE_LINE_MAX_POINTS),
    loudness: 0,
    peak: 0,
  };
  let lastMs = 0;
  let scopePeak = 0;

  const fillWave = (frame: VisualFrame | null, nowMs: number) => {
    bands.step(nowMs, frame?.bands ?? null);
    for (let point = 0; point < state.count; point += 1) {
      const position = point / (state.count - 1);
      let height = 0;
      for (const [index, partial] of WAVE_PARTIALS.entries()) {
        height +=
          partial.weight *
          (bands.levels[index] ?? 0) *
          Math.sin(TWO_PI * partial.cycles * position + (phases[index] ?? 0));
      }
      targets[point] = clamp(height * sensitivity, -1, 1);
    }
  };

  const fillTargets = (nowMs: number, frame: VisualFrame | null) => {
    const { count } = state;
    if (loading) {
      const seconds = reducedMotion
        ? LOADING_REST_SECONDS
        : nowMs / MS_PER_SECOND;
      for (let point = 0; point < count; point += 1) {
        targets[point] = loadingPulse(point / (count - 1), seconds);
      }
      return;
    }
    const samples = frame?.timeDomain;
    if (mode === "scope" && samples && samples.length > 1) {
      scopePeak = Math.max(
        peakOf(samples, samples.length),
        scopePeak * SCOPE_PEAK_RELEASE
      );
      const gain =
        sensitivity * Math.min(SCOPE_MAX_GAIN, SCOPE_TARGET / (scopePeak || 1));
      fillScope(samples, targets, count, gain);
      return;
    }
    fillWave(frame, nowMs);
  };

  const ease = (elapsedMs: number) => {
    const share = reducedMotion
      ? 1
      : 1 - EASE_PER_FRAME ** (elapsedMs / FRAME_MS);
    for (let point = 0; point < state.count; point += 1) {
      const height = state.heights[point] ?? 0;
      state.heights[point] = height + ((targets[point] ?? 0) - height) * share;
    }
    const release = LOUDNESS_RELEASE ** (elapsedMs / FRAME_MS);
    state.loudness = Math.max(
      peakOf(state.heights, state.count),
      state.loudness * release
    );
  };

  const step = (nowMs: number, frame: VisualFrame | null, count: number) => {
    const elapsedMs = lastMs === 0 ? FRAME_MS : nowMs - lastMs;
    lastMs = nowMs;
    state.count = clamp(Math.round(count), 2, WAVE_LINE_MAX_POINTS);
    if (!reducedMotion) {
      const seconds = clamp(elapsedMs / MS_PER_SECOND, 0, MAX_STEP_SECONDS);
      for (const [index, partial] of WAVE_PARTIALS.entries()) {
        phases[index] =
          ((phases[index] ?? 0) + partial.drift * seconds) % TWO_PI;
      }
    }
    fillTargets(nowMs, frame);
    state.peak = peakOf(targets, state.count);
    ease(elapsedMs);
    return !loading && state.peak >= SIGNAL_THRESHOLD;
  };

  return Object.assign(state, { step });
};

const SECONDS_PER_MINUTE = 60;
const SECONDS_PER_HOUR = 3600;
const MINUS_SIGN = "−";

export interface FormatTimeOptions {
  /** Prefix with "−", for time remaining. */
  remaining?: boolean;
  /** Always show hours. */
  hours?: boolean;
}

const pad = (value: number): string => String(value).padStart(2, "0");

/** Formats seconds as `m:ss`, or `h:mm:ss` from one hour. */
export const formatTime = (
  seconds: number,
  options: FormatTimeOptions = {}
): string => {
  const total = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const hours = Math.floor(total / SECONDS_PER_HOUR);
  const minutes = Math.floor((total % SECONDS_PER_HOUR) / SECONDS_PER_MINUTE);
  const secs = total % SECONDS_PER_MINUTE;
  const prefix = options.remaining ? MINUS_SIGN : "";

  if (hours > 0 || options.hours) {
    return `${prefix}${hours}:${pad(minutes)}:${pad(secs)}`;
  }
  return `${prefix}${minutes}:${pad(secs)}`;
};

type FrameListener = (nowMs: number) => void;
type FramePhase = "update" | "paint";

const listeners = {
  paint: new Set<FrameListener>(),
  update: new Set<FrameListener>(),
};
let handle: number | null = null;
let ticking = false;

const hasListeners = () => listeners.update.size + listeners.paint.size > 0;

const reportError = (error: unknown) => {
  queueMicrotask(() => {
    throw error;
  });
};

const tick = (nowMs: number) => {
  handle = null;
  ticking = true;
  for (const phase of [listeners.update, listeners.paint]) {
    for (const listener of phase) {
      try {
        listener(nowMs);
      } catch (error) {
        reportError(error);
      }
    }
  }
  ticking = false;
  if (hasListeners() && handle === null) {
    handle = requestAnimationFrame(tick);
  }
};

/**
 * Runs sources in the update phase, then renderers in the default paint phase.
 * One loop serves the whole page and stops when nothing is subscribed.
 * The browser pauses it while the tab is hidden.
 */
export const subscribeFrame = (
  listener: FrameListener,
  phase: FramePhase = "paint"
): (() => void) => {
  listeners[phase].add(listener);
  if (
    handle === null &&
    !ticking &&
    typeof requestAnimationFrame === "function"
  ) {
    handle = requestAnimationFrame(tick);
  }
  return () => {
    listeners[phase].delete(listener);
    if (!hasListeners() && handle !== null) {
      cancelAnimationFrame(handle);
      handle = null;
    }
  };
};

/** One frame of a task. Return true while the task needs another frame. */
export type FrameTaskStep = (nowMs: number) => boolean;

export interface FrameTask {
  /** Runs the step again from the next frame, if the task is asleep. */
  wake: () => void;
  /** Stops the task for good. A stopped task ignores `wake`. */
  stop: () => void;
}

/**
 * Runs `step` on the shared loop for as long as it returns true. When it
 * returns false the task sleeps and requests no frames until `wake()`, so a
 * settled, silent or hidden painter costs nothing. The task starts awake.
 */
export const createFrameTask = (step: FrameTaskStep): FrameTask => {
  let stopped = false;
  let unsubscribe: (() => void) | null = null;

  const sleep = () => {
    unsubscribe?.();
    unsubscribe = null;
  };

  const run = (nowMs: number) => {
    if (!step(nowMs)) {
      sleep();
    }
  };

  const wake = () => {
    if (!stopped && unsubscribe === null) {
      unsubscribe = subscribeFrame(run);
    }
  };

  wake();

  return {
    stop: () => {
      stopped = true;
      sleep();
    },
    wake,
  };
};

/** The longest step a painter clock takes, so waking never jumps. */
export const MAX_FRAME_GAP_MS = 100;

/**
 * A clock that follows the frames but never advances more than
 * `MAX_FRAME_GAP_MS` at once. A painter that slept, or ran in a hidden tab,
 * resumes its ballistics where they were instead of jumping to the end.
 */
export const createPainterClock = (): ((nowMs: number) => number) => {
  let lastMs: number | null = null;
  let clockMs = 0;
  return (nowMs) => {
    if (lastMs !== null) {
      clockMs += Math.min(Math.max(0, nowMs - lastMs), MAX_FRAME_GAP_MS);
    }
    lastMs = nowMs;
    return clockMs;
  };
};

import type { FrameSource } from "$LIB$/audio/types.js";

export interface FrameEmitter<T> extends FrameSource<T> {
  /** Sends a frame to every subscriber. */
  emit: (frame: T) => void;
  /** The last frame emitted, if any. */
  readonly latest: T | undefined;
}

/**
 * Creates a frame source you push to yourself: from a WebSocket, a worker, a
 * native bridge or a test.
 */
export const createFrameEmitter = <T>(): FrameEmitter<T> => {
  const subscribers = new Set<(frame: T) => void>();
  let latest: T | undefined;

  return {
    emit: (frame) => {
      latest = frame;
      for (const subscriber of subscribers) {
        subscriber(frame);
      }
    },
    get latest() {
      return latest;
    },
    subscribe: (listener) => {
      subscribers.add(listener);
      return () => {
        subscribers.delete(listener);
      };
    },
  };
};

export interface FrameRelay<T> extends FrameSource<T> {
  /** Forwards frames from `source`. Subscribers stay attached when it changes. */
  setSource: (source: FrameSource<T> | null) => void;
}

/**
 * A frame source whose upstream can be swapped. Components keep a stable
 * subscription while the audio behind it is rebuilt.
 */
export const createFrameRelay = <T>(): FrameRelay<T> => {
  const subscribers = new Set<(frame: T) => void>();
  let source: FrameSource<T> | null = null;
  let detach: (() => void) | null = null;

  const forward = (frame: T) => {
    for (const subscriber of subscribers) {
      subscriber(frame);
    }
  };

  const attach = () => {
    if (!detach && source && subscribers.size > 0) {
      detach = source.subscribe(forward);
    }
  };

  const release = () => {
    detach?.();
    detach = null;
  };

  return {
    setSource: (next) => {
      if (next === source) {
        return;
      }
      release();
      source = next;
      attach();
    },
    subscribe: (listener) => {
      subscribers.add(listener);
      attach();
      return () => {
        subscribers.delete(listener);
        if (subscribers.size === 0) {
          release();
        }
      };
    },
  };
};

import type { VisualFrame } from "$LIB$/audio/types.js";

export const appendHistory = (
  frame: VisualFrame,
  level: number,
  nowMs: number,
  intervalMs: number
): void => {
  const interval = Number.isFinite(intervalMs) ? Math.max(0, intervalMs) : 0;
  const elapsed = nowMs - (frame.historyUpdatedAt ?? 0);
  if (elapsed < interval || frame.history.length === 0) {
    return;
  }

  frame.historyIntervalMs = interval;
  frame.historyUpdatedAt = nowMs;
  const size = frame.history.length;
  if (frame.historyLength < size) {
    frame.history[(frame.historyStart + frame.historyLength) % size] = level;
    frame.historyLength += 1;
  } else {
    frame.historyPreviousLevel = frame.history[frame.historyStart];
    frame.history[frame.historyStart] = level;
    frame.historyStart = (frame.historyStart + 1) % size;
  }
};

import { clamp } from "$LIB$/audio/decibels.js";
import type { VisualFrame } from "$LIB$/audio/types.js";

interface HistorySample {
  frame: VisualFrame;
  fromMs: number;
  toMs: number;
}

export const createHistoryPlayback = () => {
  const samples: HistorySample[] = [];
  let previousMs: number | undefined;
  let previousLength = 0;
  let intervalMs: number | undefined;

  const clear = () => {
    samples.length = 0;
    previousMs = undefined;
    previousLength = 0;
    intervalMs = undefined;
  };

  const read = (
    frame: VisualFrame,
    nowMs: number
  ): { frame: VisualFrame; progress: number } => {
    const time = frame.historyUpdatedAt;
    const interval = frame.historyIntervalMs;
    if (
      time === undefined ||
      !Number.isFinite(time) ||
      interval === undefined ||
      !Number.isFinite(interval) ||
      interval <= 0 ||
      frame.historyLength === 0
    ) {
      clear();
      return { frame, progress: 1 };
    }
    if (
      intervalMs !== interval ||
      frame.historyLength < previousLength ||
      (previousMs !== undefined && time < previousMs)
    ) {
      clear();
    }
    intervalMs = interval;
    previousLength = frame.historyLength;
    if (time !== previousMs) {
      samples.push({
        frame: { ...frame, history: new Float32Array(frame.history) },
        fromMs: previousMs ?? time - interval,
        toMs: time,
      });
      previousMs = time;
    }

    const displayMs = nowMs - interval * 2;
    while (samples.length > 1 && (samples[0]?.toMs ?? 0) <= displayMs) {
      samples.shift();
    }
    const [sample] = samples;
    if (!sample) {
      return { frame, progress: 1 };
    }
    return {
      frame: sample.frame,
      progress: clamp(
        (displayMs - sample.fromMs) / (sample.toMs - sample.fromMs),
        0,
        1
      ),
    };
  };

  return { clear, read };
};
